#!/bin/sh
# Guards the manual security hardening applied to .github/workflows/release.yml.
#
# release.yml carries a "This file was autogenerated by dist" header, and
# `dist generate` — which runs as part of routine dist config changes — rewrites
# it from cargo-dist's template, silently discarding every change below. Without
# this check that regression is invisible: the workflow keeps working, just
# without the hardening. If this script fails after a legitimate regeneration,
# re-apply the hardening rather than relaxing the check.

set -eu

WORKFLOW="${1:-.github/workflows/release.yml}"
FAIL=0

pass() { echo "  PASS: $1"; }
fail() { echo "  FAIL: $1"; FAIL=1; }

if [ ! -f "$WORKFLOW" ]; then
    echo "workflow not found: $WORKFLOW" >&2
    exit 1
fi

echo "==> Workflow hardening: $WORKFLOW"

# 1. Third-party actions must be pinned to a commit SHA. Any mutable ref —
#    a tag (@v6), a branch (@main), @latest — lets whoever controls it change
#    what runs in a job holding our publish tokens.
#
#    This asserts the allowed shape rather than blocklisting known-bad ones:
#    a blocklist of "@v<digit>" silently passes @main, @latest and @1.2.3,
#    which is worse than no check because CI then reports "intact".
UNPINNED=$(
    grep -nE '^[[:space:]]*(-[[:space:]]*)?uses:' "$WORKFLOW" |
        grep -vE 'uses:[[:space:]]*[^@[:space:]]+@[0-9a-f]{40}([[:space:]]|$)' || true
)
if [ -n "$UNPINNED" ]; then
    echo "    unpinned:"
    echo "$UNPINNED" | sed 's/^/      /'
    fail "every action must be pinned to a 40-char commit SHA"
else
    pass "all actions pinned to commit SHAs"
fi

# 2. No pipe-to-shell installs: the fetched script is unauthenticated and
#    executes with the job's credentials.
if grep -nE 'curl[^|]*\|\s*(sh|bash)' "$WORKFLOW" >/dev/null 2>&1; then
    echo "    found:"
    grep -nE 'curl[^|]*\|\s*(sh|bash)' "$WORKFLOW" | sed 's/^/      /'
    fail "pipe-to-shell install reintroduced"
else
    pass "no pipe-to-shell installs"
fi

# 3. The rustup bootstrap must verify what it downloaded.
if grep -qF 'rustup-init' "$WORKFLOW"; then
    if grep -qF 'sha256sum -c -' "$WORKFLOW"; then
        pass "rustup-init download is checksum-verified"
    else
        fail "rustup-init is fetched without a checksum check"
    fi
else
    pass "no rustup-init bootstrap present"
fi

# 4. npm publishes via Trusted Publishing (OIDC), not a stored token, and only
#    stages the version: a maintainer approves it with 2FA. The dist template
#    runs a direct `npm publish` with NODE_AUTH_TOKEN: secrets.NPM_TOKEN, so a
#    regeneration silently brings both back.
if grep -qE 'npm (stage )?publish' "$WORKFLOW"; then
    if grep -nE 'secrets\.NPM_TOKEN|NODE_AUTH_TOKEN' "$WORKFLOW" >/dev/null; then
        echo "    found:"
        grep -nE 'secrets\.NPM_TOKEN|NODE_AUTH_TOKEN' "$WORKFLOW" | sed 's/^/      /'
        fail "npm publish uses a stored token instead of Trusted Publishing"
    elif ! grep -qE '^[[:space:]]*id-token:[[:space:]]*write' "$WORKFLOW"; then
        fail "npm publish without id-token: write cannot use Trusted Publishing"
    elif grep -nE 'npm publish' "$WORKFLOW" | grep -vE '^[0-9]+:[[:space:]]*#' >/dev/null; then
        echo "    found:"
        grep -nE 'npm publish' "$WORKFLOW" | grep -vE '^[0-9]+:[[:space:]]*#' | sed 's/^/      /'
        fail "direct npm publish bypasses staged publishing (use npm stage publish)"
    else
        pass "npm stages via Trusted Publishing (maintainer approves with 2FA)"
    fi
else
    pass "no npm publish present"
fi

# 5. Release archives carry GitHub build provenance. Only the release workflow
#    builds them (it is the one that runs `dist build`).
if grep -qE 'dist build' "$WORKFLOW"; then
    if ! grep -qE 'uses:[[:space:]]*actions/attest(-build-provenance)?@' "$WORKFLOW"; then
        fail "release archives are built without an attestation step"
    elif ! grep -qE '^[[:space:]]*"?attestations"?:[[:space:]]*"?write' "$WORKFLOW"; then
        fail "attestation step lacks attestations: write"
    else
        pass "release archives get build provenance attestations"
    fi
else
    pass "no release build present"
fi

echo ""
if [ "$FAIL" -eq 0 ]; then
    echo "Workflow hardening intact: $WORKFLOW"
else
    echo "Workflow hardening REGRESSED ($WORKFLOW) — see failures above" >&2
    exit 1
fi
